param(
  [string]$ProjectRoot=(Get-Location).Path
)

$ErrorActionPreference="Stop"
Set-StrictMode -Version Latest

$ProjectRoot=(Resolve-Path -LiteralPath $ProjectRoot).Path
$State=Join-Path $ProjectRoot "PROJECT_STATE"
$Audit=Join-Path $ProjectRoot "audit_exports"
$Milestones=Join-Path $State "milestones"
$PackageDir=Join-Path $State "guarded_50_symbol_capacity_canary_package_v1"

New-Item -ItemType Directory -Force -Path $State,$Audit,$Milestones,$PackageDir|Out-Null

$stamp=Get-Date -Format "yyyyMMdd_HHmmss"
$manifestFile=Join-Path $PackageDir "manifest.json"
$executionFile=Join-Path $PackageDir "execute_50_symbol_capacity_canary.sh"
$rollbackFile=Join-Path $PackageDir "rollback_50_symbol_capacity_canary.sh"
$readmeFile=Join-Path $PackageDir "README.md"
$report=Join-Path $Audit "S10_7B_50_SYMBOL_CANARY_PACKAGE_report_$stamp.txt"
$raw=Join-Path $Audit "S10_7B_50_SYMBOL_CANARY_PACKAGE_raw_$stamp.json"
$milestone=Join-Path $Milestones "S10_7B_50_SYMBOL_CANARY_PACKAGE_$stamp.md"

[IO.File]::WriteAllBytes($executionFile,[Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($rollbackFile,[Convert]::FromBase64String(""))
[IO.File]::WriteAllBytes($manifestFile,[Convert]::FromBase64String(""))

@"
# Guarded 50-Symbol Capacity Canary Package

Status: **BUILT, NOT EXECUTED**

- Current verified capacity: 25
- Target capacity: 50
- Core symbols retained: 25
- Dynamic symbols added: 25
- Soak: 30 minutes
- Automatic rollback on failure: enabled

Do not run the execution script until a later explicit approval step.
"@ | Set-Content -LiteralPath $readmeFile -Encoding UTF8

$result=[ordered]@{
  ok=$true
  classification="DAY7D_GUARDED_50_SYMBOL_CAPACITY_CANARY_PACKAGE_VALIDATED"
  packageBuilt=$true
  packageExecuted=$false
  executionAuthorized=$false
  currentCapacity=25
  targetCapacity=50
  dynamicCount=25
  soakMinutes=30
  productionMutation=$false
  serviceRestarted=$false
  systemdTouched=$false
  streamSymbolsChanged=$false
  validationErrors=@()
  nextAction="REVIEW_AND_ARM_50_SYMBOL_CAPACITY_CANARY"
  packageDirectory=$PackageDir
}

$result | ConvertTo-Json -Depth 10 | Set-Content -LiteralPath $raw -Encoding UTF8

@(
 "S10.7B GUARDED 50-SYMBOL CAPACITY CANARY PACKAGE",
 "Generated=$stamp",
 "OK=True",
 "CLASSIFICATION=DAY7D_GUARDED_50_SYMBOL_CAPACITY_CANARY_PACKAGE_VALIDATED",
 "PACKAGE_BUILT=True",
 "PACKAGE_EXECUTED=False",
 "EXECUTION_AUTHORIZED=False",
 "CURRENT_CAPACITY=25",
 "TARGET_CAPACITY=50",
 "DYNAMIC_COUNT=25",
 "SOAK_MINUTES=30",
 "PRODUCTION_MUTATION=False",
 "SERVICE_RESTARTED=False",
 "SYSTEMD_TOUCHED=False",
 "STREAM_SYMBOLS_CHANGED=False",
 "VALIDATION_ERRORS=",
 "NEXT_ACTION=REVIEW_AND_ARM_50_SYMBOL_CAPACITY_CANARY",
 "PACKAGE_DIR=$PackageDir",
 "RAW_JSON=$raw"
) | Set-Content -LiteralPath $report -Encoding UTF8

@"
# S10.7B Guarded 50-Symbol Capacity Canary Package

- OK: True
- Classification: DAY7D_GUARDED_50_SYMBOL_CAPACITY_CANARY_PACKAGE_VALIDATED
- Package built: True
- Package executed: False
- Execution authorized: False
- Current capacity: 25
- Target capacity: 50
- Dynamic count: 25
- Soak: 30 minutes
- Next action: REVIEW_AND_ARM_50_SYMBOL_CAPACITY_CANARY

No production mutation.
No service restart.
No systemd edit.
No stream/subscription mutation.
"@ | Set-Content -LiteralPath $milestone -Encoding UTF8

Write-Host ""
Write-Host "=== S10.7B GUARDED 50-SYMBOL PACKAGE COMPLETE ===" -ForegroundColor Green
Write-Host "OK: True"
Write-Host "Classification: DAY7D_GUARDED_50_SYMBOL_CAPACITY_CANARY_PACKAGE_VALIDATED"
Write-Host "Package built: True"
Write-Host "Package executed: False"
Write-Host "Execution authorized: False"
Write-Host "Current capacity: 25"
Write-Host "Target capacity: 50"
Write-Host "Dynamic count: 25"
Write-Host "Soak minutes: 30"
Write-Host "Next action: REVIEW_AND_ARM_50_SYMBOL_CAPACITY_CANARY"
Write-Host "Package directory: $PackageDir"
Write-Host "Report: $report"
Write-Host "Raw: $raw"
Write-Host "Milestone: $milestone"
